from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from datetime import datetime, timezone
import os, json, urllib.request, time
SYSTEM_ID='UNG-ATLAS'; VERSION='0.4.0'
app=FastAPI(title='UNG-ATLAS Control Infrastructure',version=VERSION)
SYSTEMS=[('TITAN','Enterprise Asset Management'),('MIDAS','Finance'),('NOVA','Data & Analytics'),('HERMES','Communications'),('NEMSIS','Emergency Management'),('HORUS','UAS / Aerial Operations')]
def probe(s,path='/health'):
 u=os.getenv(f'{s}_BASE_URL','').rstrip('/')
 if not u:return {'id':f'UNG-{s}','status':'unconfigured','latency_ms':None}
 t=time.perf_counter()
 try:
  with urllib.request.urlopen(u+path,timeout=3) as r: data=json.loads(r.read().decode())
  return {'id':f'UNG-{s}','status':'online' if r.status==200 else 'degraded','latency_ms':round((time.perf_counter()-t)*1000),'response':data}
 except Exception as e:return {'id':f'UNG-{s}','status':'offline','latency_ms':None,'error':type(e).__name__}
def fleet():return [probe(s) for s,_ in SYSTEMS]
@app.get('/',response_class=HTMLResponse)
def dashboard():
 cards=''.join(f'''<button class="card" data-id="{s}" data-name="{n}"><div><span class="dot" id="dot-{s}"></span><b>UNG-{s}</b></div><h3>{n}</h3><p id="st-{s}">CHECKING…</p><small id="lat-{s}">Live telemetry</small></button>''' for s,n in SYSTEMS)
 return f'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNG-ATLAS</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#07111f;color:#edf4ff;font-family:system-ui,-apple-system,sans-serif}}header{{padding:20px 24px;border-bottom:1px solid #243955;background:#0a1627;display:flex;justify-content:space-between;align-items:center}}.brand{{font-size:22px;font-weight:900}}.sub,.muted,small{{color:#8ca2c0}}.good{{color:#68e5a2}}main{{max-width:1180px;margin:auto;padding:22px}}.top{{display:grid;grid-template-columns:2fr 1fr;gap:14px}}.panel,.card{{background:#0e1c31;border:1px solid #28415f;border-radius:16px;padding:18px}}h1{{font-size:27px;margin:5px 0}}h2{{font-size:13px;letter-spacing:1.5px;color:#9eb2cf;text-transform:uppercase;margin:18px 0 12px}}.metric{{font-size:38px;font-weight:900}}.deps{{display:flex;gap:9px;flex-wrap:wrap;margin-top:15px}}.pill{{border:1px solid #304b6d;background:#101f35;border-radius:10px;padding:10px 12px;font-size:12px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}}.card{{text-align:left;color:inherit;width:100%;cursor:pointer}}.card h3{{color:#b8c8de;font-size:15px;margin:16px 0 7px}}.card p{{font-weight:800;font-size:12px;color:#e8b85e}}.dot{{display:inline-block;width:8px;height:8px;border-radius:50%;background:#e8b85e;margin-right:8px}}.online{{color:#69e6a3!important}}.offline{{color:#ff7c86!important}}.dot.online{{background:#5bdd96;box-shadow:0 0 10px #5bdd96}}.dot.offline{{background:#ff6c78}}#drawer{{display:none;margin-top:15px}}#drawer.on{{display:block}}.actions{{display:flex;gap:9px;flex-wrap:wrap;margin-top:15px}}.action{{border:1px solid #304b6d;background:#101f35;color:#dfeaff;border-radius:10px;padding:11px 13px}}#msg{{margin-top:12px;color:#6ee7a6;font-size:12px}}footer{{color:#667e9e;font-size:11px;padding:22px 0}}@media(max-width:700px){{header{{padding:17px}}main{{padding:15px}}.top,.grid{{grid-template-columns:1fr}}h1{{font-size:23px}}}}</style></head><body><header><div><div class="brand">UNG-ATLAS</div><div class="sub">National Grid Control Infrastructure</div></div><div class="good">● LIVE TELEMETRY</div></header><main><section class="top"><div class="panel"><h2>Operations Command</h2><h1>Enterprise Control Plane</h1><div class="muted">Live production health and dependency visibility.</div><div class="deps"><span class="pill">JANUS · CONNECTED</span><span class="pill">PULSAR · CONNECTED</span><span class="pill">ATLAS · ACTIVE</span></div></div><div class="panel"><h2>Fleet Readiness</h2><div id="metric" class="metric">— / 6</div><div id="fleetstate" class="muted">PROBING PRODUCTION</div></div></section><h2>Live System Registry</h2><section class="grid">{cards}</section><section id="drawer" class="panel"><h2>System Control</h2><h1 id="dn"></h1><div id="di" class="muted"></div><div class="actions"><button class="action" id="health">Run Live Health Check</button><button class="action" id="ready">Run Live Readiness Check</button></div><div id="msg"></div></section><footer>UNG-ATLAS v{VERSION} · Live Control Infrastructure</footer></main><script>let sel='';const msg=document.getElementById('msg');async function refresh(){{try{{const r=await fetch('/v1/telemetry');const x=await r.json();document.getElementById('metric').textContent=x.online+' / '+x.total;document.getElementById('fleetstate').textContent=x.online===x.total?'ALL SYSTEMS ONLINE':'ATTENTION REQUIRED';x.systems.forEach(v=>{{let s=v.id.replace('UNG-',''),p=document.getElementById('st-'+s),d=document.getElementById('dot-'+s),l=document.getElementById('lat-'+s);p.textContent=v.status.toUpperCase();p.className=v.status;d.className='dot '+v.status;l.textContent=v.latency_ms===null?'No response':v.latency_ms+' ms';}})}}catch(e){{document.getElementById('fleetstate').textContent='TELEMETRY ERROR'}}}}document.querySelectorAll('.card').forEach(b=>b.onclick=()=>{{sel=b.dataset.id;document.getElementById('dn').textContent='UNG-'+sel;document.getElementById('di').textContent=b.dataset.name;document.getElementById('drawer').classList.add('on')}});async function check(path){{if(!sel)return;msg.textContent='Checking '+sel+'…';const r=await fetch('/v1/probe/'+sel+'?path='+path);const x=await r.json();msg.textContent='UNG-'+sel+' '+path+': '+x.status.toUpperCase()+(x.latency_ms?' · '+x.latency_ms+' ms':'')}}document.getElementById('health').onclick=()=>check('/health');document.getElementById('ready').onclick=()=>check('/ready');refresh();setInterval(refresh,30000);</script></body></html>'''
@app.get('/health')
def health():return {'status':'ok','service':SYSTEM_ID,'version':VERSION}
@app.get('/ready')
def ready():
 f=fleet();return {'status':'ready' if all(x['status']=='online' for x in f) else 'degraded','service':SYSTEM_ID,'systems':f,'version':VERSION}
@app.get('/v1/telemetry')
def telemetry():
 f=fleet();return {'systems':f,'online':sum(x['status']=='online' for x in f),'total':len(f),'timestamp':datetime.now(timezone.utc).isoformat()}
@app.get('/v1/probe/{system}')
def live_probe(system:str,path:str='/health'):
 system=system.upper();return probe(system,path if path in ['/health','/ready'] else '/health') if any(system==s for s,_ in SYSTEMS) else {'status':'unknown'}
@app.get('/v1/registry')
def registry():return {'systems':[{'id':f'UNG-{s}','name':n,'url_configured':bool(os.getenv(f'{s}_BASE_URL'))} for s,n in SYSTEMS]}
